// Actuadores simulados: qué comandos soporta cada uno y en qué estado está. Los identificadores tienen que ser los registrados.
flow.set('actuadores', {
    'norte/sectorA/ventilador': { comandos: ['ENCENDER', 'APAGAR', 'FIJAR_NIVEL'], estado: 'apagado' },
    'norte/sectorA/ventana': { comandos: ['ABRIR', 'CERRAR', 'FIJAR_POSICION'], estado: 'cerrado' }
});
flow.set('memoria', {});          // id del comando → { resultado, en } durante 24 h (D-77, punto 3)
flow.set('simulacion', 'ejecutar'); // ejecutar | fallar | no_responder | rechazar
flow.set('en_vuelo', false);
node.status({ fill: 'green', shape: 'dot', text: 'simulación: ejecutar' });
return null;

// Cada 5 segundos: GET comandos (D-77, punto 4). Si el anterior no volvió, no se manda otro.

function base() { const u = env.get('INFOPONIA_URL') || ''; return u.endsWith('/') ? u : u + '/'; }
function encabezados() { return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''), 'Content-Type': 'application/json' }; }
function ahoraIso() { return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'); }

if (flow.get('en_vuelo')) return null;
flow.set('en_vuelo', true);
return { url: base() + 'comandos', headers: encabezados(), requestTimeout: 10000 };

// Un mensaje por comando entregado. Cualquier error del retiro solo se registra: el próximo retiro es en 5 s.
flow.set('en_vuelo', false);
if (msg.statusCode !== 200) {
    node.status({ fill: 'red', shape: 'ring', text: 'retiro: ' + msg.statusCode });
    return [null, { payload: msg.payload, topic: 'retiro fallido ' + msg.statusCode }];
}
const p = msg.payload || {};
const cmds = p.comandos || [];
node.status({ fill: cmds.length ? 'blue' : 'green', shape: 'dot', text: 'modo ' + p.modo + ' · ' + cmds.length + ' comando(s)' });
return [cmds.map(c => ({ comando: c })), null];

// Ejecuta (simula) un comando, con la memoria de 24 h (D-77, punto 3; regla «Comando repetido en el nodo»).

function base() { const u = env.get('INFOPONIA_URL') || ''; return u.endsWith('/') ? u : u + '/'; }
function encabezados() { return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''), 'Content-Type': 'application/json' }; }
function ahoraIso() { return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'); }

const DEJA = { ENCENDER: 'encendido', APAGAR: 'apagado', ABRIR: 'abierto', CERRAR: 'cerrado' };
const c = msg.comando;
const memoria = flow.get('memoria') || {};
const limite = Date.now() - 24 * 3600 * 1000;
for (const k of Object.keys(memoria)) if (memoria[k].en < limite) delete memoria[k];
let cuerpo;
if (memoria[c.id]) {
    cuerpo = memoria[c.id].resultado;                  // ya lo ejecutó: manda el mismo resultado, no lo repite
    node.warn('Comando ' + c.id + ' repetido: no se ejecuta otra vez.');
} else {
    const acts = flow.get('actuadores') || {};
    const a = acts[c.identificador];
    const modo = flow.get('simulacion') || 'ejecutar';
    if (modo === 'no_responder') { node.status({ fill: 'yellow', shape: 'ring', text: c.id + ': sin respuesta (simulado)' }); return null; }
    if (!a || !a.comandos.includes(c.comando) || modo === 'rechazar') {
        cuerpo = { resultado: 'rechazado', detalle: c.comando + ' no está configurado para ' + c.identificador + '.' };
    } else if (modo === 'fallar') {
        cuerpo = { resultado: 'fallo', detalle: 'Falla simulada en el intento ' + c.intento + '.' };
    } else {
        a.estado = DEJA[c.comando] || (c.comando === 'FIJAR_NIVEL' ? 'nivel:' + c.valor : 'posicion:' + c.valor);
        flow.set('actuadores', acts);
        cuerpo = { resultado: 'ejecutado', detalle: 'Ejecutado (simulado).', estado: a.estado, informado_en: ahoraIso() };
    }
    if (cuerpo.resultado !== 'fallo') memoria[c.id] = { resultado: cuerpo, en: Date.now() };
}
flow.set('memoria', memoria);
node.status({ text: c.id + ': ' + cuerpo.resultado });
return { url: base() + 'comandos/' + c.id + '/resultado', headers: encabezados(), requestTimeout: 10000,
         payload: cuerpo, comando: c, intento_envio: (msg.intento_envio || 0) + 1, limite_ms: Date.now() + c.espera_segundos * 1000 };

// Guarda el cuerpo antes de enviarlo: la respuesta reemplaza msg.payload y msg.headers.
msg.payload_enviado = msg.payload;
return msg;

// Respuesta al resultado: 200 (aceptado o ya_resuelto) termina; falla pasajera se reintenta dentro de la espera; 4xx se descarta.
const codigo = msg.statusCode;
if (codigo === 200) {
    node.status({ fill: 'green', shape: 'dot', text: msg.comando.id + ': ' + msg.payload.resultado + ' · ' + msg.payload.estado_comando });
    return [null, { payload: msg.payload, topic: 'resultado ' + msg.comando.id }];
}
if ((codigo === 429 || codigo >= 500 || typeof codigo !== 'number') && msg.intento_envio < 5) {
    const espera = Math.min(2000 * Math.pow(2, msg.intento_envio - 1), Math.max(1000, msg.limite_ms - Date.now()));
    node.status({ fill: 'yellow', shape: 'ring', text: msg.comando.id + ': reintento del resultado' });
    return [{ url: msg.url, payload: msg.payload_enviado, comando: msg.comando, intento_envio: msg.intento_envio + 1,
              limite_ms: msg.limite_ms, delay: espera }, null];
}
node.status({ fill: 'red', shape: 'dot', text: msg.comando.id + ': ' + codigo });
return [null, { payload: msg.payload, topic: 'resultado rechazado ' + codigo + ' (no se reintenta)' }];

// Vuelve a poner los encabezados (la respuesta anterior los reemplazó) antes de reenviar el mismo resultado.

function base() { const u = env.get('INFOPONIA_URL') || ''; return u.endsWith('/') ? u : u + '/'; }
function encabezados() { return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''), 'Content-Type': 'application/json' }; }
function ahoraIso() { return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'); }

msg.headers = encabezados();
msg.requestTimeout = 10000;
return msg;

// Botones del panel: cómo responde el nodo a los próximos comandos.
flow.set('simulacion', msg.payload);
node.status({ text: 'simulación: ' + msg.payload });
return null;
